import { renderItems } from "./basket-render.js";
import { sendMail } from "./mailer.js";
import type { Basket } from "./types.js";

export const REMINDER_DELAY_MS = 24 * 60 * 60 * 1000;

/** Baskets already reminded, so a second abandonment sends nothing (R2). */
const reminded = new Set<string>();

export function reminderBody(basket: Basket): string {
  return [
    `Hi ${basket.shopperName},`,
    "",
    "You left these in your basket:",
    renderItems(basket.items),
    "",
    `Pick up where you left off: https://basket.example/b/${basket.id}`,
    "",
    "— Basket",
  ].join("\n");
}

export async function sendReminder(
  basket: Basket,
  now: number,
): Promise<"sent" | "skipped"> {
  if (basket.convertedAt != null) return "skipped";
  if (reminded.has(basket.id)) return "skipped";
  if (now - basket.abandonedAt < REMINDER_DELAY_MS) return "skipped";
  await sendMail({
    to: basket.shopperEmail,
    subject: "Your basket is waiting",
    body: reminderBody(basket),
  });
  reminded.add(basket.id);
  return "sent";
}

