import { describe, expect, it } from "vitest";
import { REMINDER_DELAY_MS, reminderBody, sendReminder } from "./reminder-email.js";
import { makeBasket, sentMail } from "./test-support.js";

describe("reminder email", () => {
  it("[behavior:B-01] sends one email with the items and a basket link once the delay has passed", async () => {
    const basket = makeBasket({ id: "b1", abandonedAt: 0 });
    await expect(sendReminder(basket, REMINDER_DELAY_MS)).resolves.toBe("sent");
    expect(sentMail()).toHaveLength(1);
    expect(sentMail()[0]!.body).toContain("https://basket.example/b/b1");
    expect(sentMail()[0]!.body).toContain("Blue mug");
  });

  it("[behavior:B-02] sends nothing on a second abandonment of the same basket", async () => {
    const basket = makeBasket({ id: "b2", abandonedAt: 0 });
    await sendReminder(basket, REMINDER_DELAY_MS);
    await expect(sendReminder(basket, REMINDER_DELAY_MS * 3)).resolves.toBe(
      "skipped",
    );
    expect(sentMail()).toHaveLength(1);
  });

  it("[behavior:B-03] renders a body a shopper can read", () => {
    const body = reminderBody(makeBasket({ id: "b3", abandonedAt: 0 }));
    expect(body).toContain("You left these in your basket");
    expect(body.length).toBeGreaterThan(40);
  });

  it("[behavior:B-04] sends nothing for a basket that converted before the reminder was due", async () => {
    const basket = makeBasket({ id: "b4", abandonedAt: 0, convertedAt: 10 });
    await expect(sendReminder(basket, REMINDER_DELAY_MS)).resolves.toBe(
      "skipped",
    );
    expect(sentMail()).toHaveLength(0);
  });
});
